    (M en spin spa lo shi ff fp : Z) (LF : list fframe) (m mx : mem) (gap : list cell) (junk lj hj sh32 j3 : list byte) (bflag : byte),
  rw_cells bsegs mx spa [C8 (Z_to_bv 64 ff); CB 24 lj] -> lo <= spa ->
  rw_cells bsegs mx (spa + 32) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 32) ->
