  rw_cells bsegs mx ff [CB 248 hj; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 32 sh32] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((2, ff, fp) :: LF) mx -> fresh_frame H LF 2 ff fp -> ACONST mx -> stack0 mx lo shi ->
  munch (actor_W H lo sp M ff fp) m mx -> wmono bsegs m mx ->
  rw_cells bsegs mx M [CB 8 (firstn 8 junk)] -> APMutex mx (M + 8) 0 -> rw_cells bsegs mx (M + 48) [C4 (wz spin); CB 1 [b8 en]; CB 3 j3] ->
  aapp M 56 -> (M + 56 <= ff \/ ff + 256 <= M) -> (M + 56 <= fp \/ fp + 1 <= M) ->
  ACanaryReads mx -> AXStatics2 mx ->
  (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) -> lo + 144 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (acem_ctor_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc M en spin LF lo shi junk m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp xs1 a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) xs3 xs4 xs5 xs6 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) xs9 xs10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 P_A_CEM_EXIT) fc None mx (seg_rom bsegs)).
